-- ============================================================
-- 1) Clean old generated/test rows - OPTIMIZED
-- ============================================================
-- IMPORTANT:
--   This cleanup avoids slow DELETE conditions using OR + IN.
--   It builds small temp tables first, then deletes by JOIN/USING.
--
-- Generated ID ranges:
--   customer_id: 900000001 - 900999999
--   account_id : 910000001 - 910999999
--
-- It also removes old generated rows with tech_account_no like 'RIM-%'.
-- ============================================================

-- Optional safety timeout. Increase or remove if your database is slow.
SET LOCAL lock_timeout = '10s';
SET LOCAL statement_timeout = '10min';

-- Helpful indexes for this cleanup and future testing.
-- These are normal indexes because CREATE INDEX CONCURRENTLY cannot run inside BEGIN.
CREATE INDEX IF NOT EXISTS idx_tmp_ref_customer_misc_info_customer_id
ON sdedba.ref_customer_misc_info(customer_id);

CREATE INDEX IF NOT EXISTS idx_tmp_ref_customer_misc_info_tech_account_no
ON sdedba.ref_customer_misc_info(tech_account_no);

CREATE INDEX IF NOT EXISTS idx_tmp_fin_account_info_account_id
ON findba.fin_account_info(account_id);

CREATE INDEX IF NOT EXISTS idx_tmp_fin_account_info_customer_id
ON findba.fin_account_info(customer_id);

CREATE INDEX IF NOT EXISTS idx_tmp_fin_account_item_account_id
ON findba.fin_account_item(account_id);

-- Old generated customers by generated customer_id range.
CREATE TEMP TABLE tmp_old_generated_customers AS
SELECT DISTINCT mi.customer_id
FROM sdedba.ref_customer_misc_info mi
WHERE mi.customer_id BETWEEN 900000001 AND 900999999;

-- Add old generated customers by RIM-* pattern separately to avoid OR.
INSERT INTO tmp_old_generated_customers (customer_id)
SELECT DISTINCT mi.customer_id
FROM sdedba.ref_customer_misc_info mi
WHERE mi.tech_account_no LIKE 'RIM-%'
  AND NOT EXISTS (
      SELECT 1
      FROM tmp_old_generated_customers t
      WHERE t.customer_id = mi.customer_id
  );

CREATE INDEX tmp_old_generated_customers_idx
ON tmp_old_generated_customers(customer_id);

ANALYZE tmp_old_generated_customers;

-- Old generated accounts by generated account_id range.
CREATE TEMP TABLE tmp_old_generated_accounts AS
SELECT DISTINCT a.account_id
FROM findba.fin_account_info a
WHERE a.account_id BETWEEN 910000001 AND 910999999;

-- Add old generated accounts linked to old generated customers separately to avoid OR.
INSERT INTO tmp_old_generated_accounts (account_id)
SELECT DISTINCT a.account_id
FROM findba.fin_account_info a
JOIN tmp_old_generated_customers t
    ON t.customer_id = a.customer_id
WHERE NOT EXISTS (
    SELECT 1
    FROM tmp_old_generated_accounts x
    WHERE x.account_id = a.account_id
);

CREATE INDEX tmp_old_generated_accounts_idx
ON tmp_old_generated_accounts(account_id);

ANALYZE tmp_old_generated_accounts;

-- Delete children first.
DELETE FROM findba.fin_account_item ai
USING tmp_old_generated_accounts t
WHERE ai.account_id = t.account_id;

-- Delete account headers.
DELETE FROM findba.fin_account_info a
USING tmp_old_generated_accounts t
WHERE a.account_id = t.account_id;

-- Delete misc info.
DELETE FROM sdedba.ref_customer_misc_info mi
USING tmp_old_generated_customers t
WHERE mi.customer_id = t.customer_id;

-- Delete customers.
DELETE FROM sdedba.ref_customer c
USING tmp_old_generated_customers t
WHERE c.customer_id = t.customer_id;

-- ============================================================
-- 2) Prepare clean logical IDs from the CSV
-- ============================================================

CREATE TEMP TABLE tmp_distinct_rims AS
SELECT
    rimno,
    900000000 + DENSE_RANK() OVER (ORDER BY rimno) AS customer_id
FROM (
    SELECT DISTINCT rimno
    FROM tmp_query_account_data
    WHERE COALESCE(rimno, '') <> ''
) x;

CREATE TEMP TABLE tmp_rows AS
SELECT
    ROW_NUMBER() OVER (ORDER BY d.rimno, d.productcode, d.productid, d.opendate) AS rn,
    r.customer_id,
    910000000 + ROW_NUMBER() OVER (ORDER BY d.rimno, d.productcode, d.productid, d.opendate) AS account_id,
    d.*
FROM tmp_query_account_data d
JOIN tmp_distinct_rims r
    ON r.rimno = d.rimno;

-- ============================================================
-- 3) Insert customers
-- ============================================================

INSERT INTO sdedba.ref_customer (
    customer_id
)
SELECT
    customer_id
FROM tmp_distinct_rims
ON CONFLICT DO NOTHING;

-- ============================================================
-- 4) Insert customer misc info
-- ============================================================

INSERT INTO sdedba.ref_customer_misc_info (
    customer_id,
    tech_account_no
)
SELECT
    customer_id,
    rimno
FROM tmp_distinct_rims
ON CONFLICT DO NOTHING;

-- ============================================================
-- 5) Insert account headers
-- ============================================================
-- account_reason_code is mapped from ref_sysp71.lin_name.
-- If the reason text does not exist in ref_sysp71, it remains NULL.
-- ============================================================

INSERT INTO findba.fin_account_info (
    account_id,
    customer_id,
    cur_id,
    account_reason_code,
    iban_number,
    creation_date
)
SELECT
    account_id,
    customer_id,
    NULLIF(currencyid, '')::numeric AS cur_id,
    (
        SELECT p.lin_code
        FROM ref_sysp71 p
        WHERE p.lin_name = NULLIF(t.reasontoopenaccount, '')
        LIMIT 1
    ) AS account_reason_code,
    NULLIF(ibannumber, '') AS iban_number,
    CASE
        WHEN NULLIF(insertiondate, '') IS NULL THEN NULL
        ELSE TO_DATE(insertiondate, 'DD-MON-YY')
    END AS creation_date
FROM tmp_rows t
ON CONFLICT DO NOTHING;

-- ============================================================
-- 6) Insert account items
-- ============================================================

INSERT INTO findba.fin_account_item (
    account_id,
    itm_id,
    tech_lgcy_item_code,
    account_itm_reference,
    origination_date,
    lgcy_expiry_date,
    status_code
)
SELECT
    account_id,
    NULLIF(productid, '')::numeric AS itm_id,
    NULLIF(productclientcode, '') AS tech_lgcy_item_code,
    NULLIF(productcode, '') AS account_itm_reference,
    CASE
        WHEN NULLIF(opendate, '') IS NULL THEN NULL
        ELSE TO_DATE(opendate, 'DD-MON-YY')
    END AS origination_date,
    CASE
        WHEN NULLIF(enddate, '') IS NULL THEN NULL
        ELSE TO_DATE(enddate, 'DD-MON-YY')
    END AS lgcy_expiry_date,
    NULLIF(statuscode, '')::numeric AS status_code
FROM tmp_rows
ON CONFLICT DO NOTHING;

-- ============================================================
-- 7) Validation
-- ============================================================

-- Number of rows staged from CSV.
SELECT COUNT(*) AS staged_csv_rows
FROM tmp_query_account_data;

-- Number of customers inserted/generated from CSV RIMNO.
SELECT COUNT(*) AS generated_customers
FROM tmp_distinct_rims;

-- Number of account rows inserted/generated from CSV.
SELECT COUNT(*) AS generated_account_rows
FROM tmp_rows;

-- Check how many rows your original query should return for generated data.
SELECT COUNT(*) AS expected_query_rows
FROM sdedba.ref_customer c
JOIN sdedba.ref_customer_misc_info mi
    ON c.customer_id = mi.customer_id
LEFT JOIN findba.fin_account_info a
    ON c.customer_id = a.customer_id
JOIN findba.fin_account_item ai
    ON a.account_id = ai.account_id
WHERE c.customer_id BETWEEN 900000001 AND 900999999;

COMMIT;
